package com.grape.player

import org.junit.Test
import org.junit.Assert.assertTrue

/**
 * QRC 解密回归测试：密文来自真实接口返回（QQ 歌曲 Lemon / songid 213086592 的译文），
 * 标准答案由 Web 版 qrc-decoder 产出（含中文译文行「如果只是一场梦」）。
 * 跑在 PC JVM 上（./gradlew :app:testDebugUnitTest），与手机端共用同一份实现。
 */
class QrcCodecTest {

    @Test
    fun decryptQrc_translatesToPlainLrc() {
        val hex = """  """
        val text = com.grape.player.util.QrcCodec.decryptQrc(hex.trim())
        println(text.lineSequence().take(12).joinToString("\n"))
        assertTrue("解密结果应包含 LRC 时间戳", text.contains(Regex("\\[\\d{2}:\\d{2}\\.")))
        assertTrue("解密结果应包含中文译文", text.contains("如果只是一场梦"))
    }
}
